    culture:
      "澳大利亚是移民国家，官方语言英语，口音和用词有本地特色（把 afternoon 说成 arvo 之类）。社会节奏相对松弛，重视户外生活和周末，商店和不少景点在周日和公共假日会提早关门或不营业。原住民是这片大陆最早的居民，有数万年的连续文化，很多自然圣地和地名属于原住民，参观时按当地指引来。餐厅、出租车给小费不是义务。",
